public class IrohFfiException: UniffiException {
    IrohFfiException() : base() {}
    IrohFfiException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    public class InvalidSecretKey : IrohFfiException {
        public InvalidSecretKey() : base() {}
    }
    
    
    public class InvalidNodeId : IrohFfiException {
        public InvalidNodeId() : base() {}
    }
    
    
    public class EndpointNotInitialized : IrohFfiException {
        public EndpointNotInitialized() : base() {}
    }
    
    
    
    public class ConnectFailed : IrohFfiException {
        // Members
        public string @detail;

        // Constructor
        public ConnectFailed(
                string @detail) : base(
                "@detail" + "=" + @detail) {

            this.@detail = @detail;
        }
    }
    
    
    public class StreamFailed : IrohFfiException {
        // Members
        public string @detail;

        // Constructor
        public StreamFailed(
                string @detail) : base(
                "@detail" + "=" + @detail) {

            this.@detail = @detail;
        }
    }
    
    
    public class AcceptFailed : IrohFfiException {
        // Members
        public string @detail;

        // Constructor
        public AcceptFailed(
                string @detail) : base(
                "@detail" + "=" + @detail) {

            this.@detail = @detail;
        }
    }
    
    
    public class ShutdownFailed : IrohFfiException {
        // Members
        public string @detail;

        // Constructor
        public ShutdownFailed(
                string @detail) : base(
                "@detail" + "=" + @detail) {

            this.@detail = @detail;
        }
    }
    
    
    public class RuntimeFailed : IrohFfiException {
        // Members
        public string @detail;

        // Constructor
        public RuntimeFailed(
                string @detail) : base(
                "@detail" + "=" + @detail) {

            this.@detail = @detail;
        }
    }
    

    
}

class FfiConverterTypeIrohFfiError : FfiConverterRustBuffer<IrohFfiException>, CallStatusErrorHandler<IrohFfiException> {
    public static FfiConverterTypeIrohFfiError INSTANCE = new FfiConverterTypeIrohFfiError();

    public override IrohFfiException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new IrohFfiException.InvalidSecretKey();
            case 2:
                return new IrohFfiException.InvalidNodeId();
            case 3:
                return new IrohFfiException.EndpointNotInitialized();
            case 4:
                return new IrohFfiException.ConnectFailed(
                    FfiConverterString.INSTANCE.Read(stream));
            case 5:
                return new IrohFfiException.StreamFailed(
                    FfiConverterString.INSTANCE.Read(stream));
            case 6:
                return new IrohFfiException.AcceptFailed(
                    FfiConverterString.INSTANCE.Read(stream));
            case 7:
                return new IrohFfiException.ShutdownFailed(
                    FfiConverterString.INSTANCE.Read(stream));
            case 8:
                return new IrohFfiException.RuntimeFailed(
                    FfiConverterString.INSTANCE.Read(stream));
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeIrohFfiError.Read()", value));
        }
    }

    public override int AllocationSize(IrohFfiException value) {
        switch (value) {

            case IrohFfiException.InvalidSecretKey variant_value:
                return 4;

            case IrohFfiException.InvalidNodeId variant_value:
                return 4;

            case IrohFfiException.EndpointNotInitialized variant_value:
                return 4;

            case IrohFfiException.ConnectFailed variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@detail);

            case IrohFfiException.StreamFailed variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@detail);

            case IrohFfiException.AcceptFailed variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@detail);

            case IrohFfiException.ShutdownFailed variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@detail);

            case IrohFfiException.RuntimeFailed variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@detail);
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeIrohFfiError.AllocationSize()", value));
        }
    }

    public override void Write(IrohFfiException value, BigEndianStream stream) {
        switch (value) {
            case IrohFfiException.InvalidSecretKey variant_value:
                stream.WriteInt(1);
                break;
            case IrohFfiException.InvalidNodeId variant_value:
                stream.WriteInt(2);
                break;
            case IrohFfiException.EndpointNotInitialized variant_value:
                stream.WriteInt(3);
                break;
            case IrohFfiException.ConnectFailed variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.@detail, stream);
                break;
            case IrohFfiException.StreamFailed variant_value:
                stream.WriteInt(5);
                FfiConverterString.INSTANCE.Write(variant_value.@detail, stream);
                break;
            case IrohFfiException.AcceptFailed variant_value:
                stream.WriteInt(6);
                FfiConverterString.INSTANCE.Write(variant_value.@detail, stream);
                break;
            case IrohFfiException.ShutdownFailed variant_value:
                stream.WriteInt(7);
                FfiConverterString.INSTANCE.Write(variant_value.@detail, stream);
                break;
            case IrohFfiException.RuntimeFailed variant_value:
                stream.WriteInt(8);
                FfiConverterString.INSTANCE.Write(variant_value.@detail, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeIrohFfiError.Write()", value));
        }
    }
}




class FfiConverterOptionalUInt64: FfiConverterRustBuffer<ulong?> {
    public static FfiConverterOptionalUInt64 INSTANCE = new FfiConverterOptionalUInt64();

    public override ulong? Read(BigEndianStream stream) {
        if (stream.ReadByte() == 0) {
            return null;
        }
        return FfiConverterUInt64.INSTANCE.Read(stream);
    }

    public override int AllocationSize(ulong? value) {
        if (value == null) {
            return 1;
        } else {
            return 1 + FfiConverterUInt64.INSTANCE.AllocationSize((ulong)value);
        }
    }

    public override void Write(ulong? value, BigEndianStream stream) {
        if (value == null) {
            stream.WriteByte(0);
        } else {
            stream.WriteByte(1);
            FfiConverterUInt64.INSTANCE.Write((ulong)value, stream);
        }
    }
}




